namespace MuseRAM.App;

public enum UiLanguage
{
    ChineseSimplified,
    English
}

public sealed record UiLanguageOption(UiLanguage Language, string Code, string DisplayName);

public static class UiLanguageCatalog
{
    public static IReadOnlyList<UiLanguageOption> Options { get; } = new[]
    {
        new UiLanguageOption(UiLanguage.ChineseSimplified, "zh-CN", "简体中文"),
        new UiLanguageOption(UiLanguage.English, "en", "English")
    };

    public static UiLanguage FromCode(string? code) =>
        Options.FirstOrDefault(option => option.Code.Equals(code, StringComparison.OrdinalIgnoreCase))?.Language ??
        UiLanguage.ChineseSimplified;

    public static string ToCode(UiLanguage language) =>
        Options.First(option => option.Language == language).Code;
}

