        ["Lite"] = "Lite", ["Turbo"] = "Turbo", ["Ultimate"] = "Ultimate", ["ProfileHelpTitle"] = "Profile guide", ["ProfileHelpIntro"] = "Choose cleanup intensity for the current workload. The selection applies immediately to previews, manual optimization, and automatic optimization.",
